//! Golden-bytes tests pinning the wire codec to the legacy implementation.
//!
//! The expected hex vectors were generated by encoding these exact messages
//! with `legacy/subduction_core` (`MemorySigner` seeded with `[42u8; 32]`,
//! so the ed25519 signatures are deterministic). Any change to these bytes
//! is a wire-compatibility break — see `design/sans-io.md`.

use std::collections::BTreeSet;

use future_form::Sendable;
use sedimentree_core::{
    blob::{Blob, BlobMeta},
    crypto::fingerprint::{Fingerprint, FingerprintSeed},
    fragment::Fragment,
    id::SedimentreeId,
    loose_commit::{id::CommitId, LooseCommit},
    sedimentree::FingerprintSummary,
};
use subduction_crypto::{signed::Signed, signer::memory::MemorySigner};
use subduction_protocol::{
    peer_id::PeerId,
    remote_heads::RemoteHeads,
    wire::{
        BatchSyncRequest, BatchSyncResponse, DataRequestRejected, RemoveSubscriptions, RequestId,
        RequestedData, SyncDiff, SyncMessage, SyncResult,
    },
};
use testresult::TestResult;

fn from_hex(parts: &[&str]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let joined: String = parts.concat();
    if !joined.len().is_multiple_of(2) {
        return Err("hex string must have even length".into());
    }
    (0..joined.len())
        .step_by(2)
        .map(|i| {
            let pair = joined.get(i..i + 2).ok_or("hex slice out of bounds")?;
            Ok(u8::from_str_radix(pair, 16)?)
        })
        .collect()
}

fn to_hex(bytes: &[u8]) -> Result<String, Box<dyn std::error::Error>> {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit(u32::from(b >> 4), 16).ok_or("nibble out of range")?);
        s.push(char::from_digit(u32::from(b & 0xf), 16).ok_or("nibble out of range")?);
    }
    Ok(s)
}

/// Shared fixture matching the legacy golden dump exactly.
struct Fixture {
    id: SedimentreeId,
    blob: Blob,
    heads: RemoteHeads,
    signed_commit: Signed<LooseCommit>,
    signed_fragment: Signed<Fragment>,
    req_id: RequestId,
}

fn fixture() -> Fixture {
    let signer = MemorySigner::from_bytes(&[42u8; 32]);
    let id = SedimentreeId::new([1u8; 32]);
    let blob = Blob::new(vec![3u8; 16]);
    let heads = RemoteHeads {
        counter: 7,
        heads: vec![CommitId::new([0xAA; 32]), CommitId::new([0xBB; 32])],
    };

    let commit = LooseCommit::new(
        id,
        CommitId::new([0x42; 32]),
        BTreeSet::from([CommitId::new([0x41; 32])]),
        BlobMeta::new(&blob),
    );
    let signed_commit =
        futures::executor::block_on(Signed::seal::<Sendable, _>(&signer, commit)).into_signed();

    let fragment = Fragment::new(
        id,
        CommitId::new([2u8; 32]),
        BTreeSet::from([CommitId::new([3u8; 32])]),
        &[],
        BlobMeta::new(&blob),
    );
    let signed_fragment =
        futures::executor::block_on(Signed::seal::<Sendable, _>(&signer, fragment)).into_signed();

    let req_id = RequestId {
        requestor: PeerId::new([7u8; 32]),
        nonce: 99,
    };

    Fixture {
        id,
        blob,
        heads,
        signed_commit,
        signed_fragment,
        req_id,
    }
}

/// Check that `msg` encodes to exactly the legacy golden bytes, and that
/// the golden bytes decode back to `msg`.
fn assert_golden(msg: &SyncMessage, golden_hex: &[&str]) -> TestResult {
    let golden = from_hex(golden_hex)?;

    let encoded = msg.encode();
    assert_eq!(
        to_hex(&encoded)?,
        to_hex(&golden)?,
        "encoding differs from legacy golden bytes",
    );

    let decoded = SyncMessage::try_decode(&golden)?;
    assert_eq!(&decoded, msg, "golden bytes decoded to a different message");
    Ok(())
}

