#[test]
fn batch_sync_request_matches_legacy() -> TestResult {
    let f = fixture();
    let msg = SyncMessage::BatchSyncRequest(BatchSyncRequest {
        id: f.id,
        req_id: f.req_id,
        fingerprint_summary: FingerprintSummary::new(
            FingerprintSeed::new(11, 22),
            BTreeSet::from([Fingerprint::from_u64(1), Fingerprint::from_u64(2)]),
            BTreeSet::from([Fingerprint::from_u64(3)]),
        ),
        subscribe: true,
    });
    assert_golden(&msg, GOLDEN_BATCH_SYNC_REQUEST)
}

#[test]
fn batch_sync_response_ok_matches_legacy() -> TestResult {
    let f = fixture();
    let msg = SyncMessage::BatchSyncResponse(BatchSyncResponse {
        req_id: f.req_id,
        id: f.id,
        result: SyncResult::Ok(SyncDiff {
            missing_commits: vec![(f.signed_commit, f.blob.clone())],
            missing_fragments: vec![(f.signed_fragment, f.blob)],
            requesting: RequestedData {
                commit_fingerprints: vec![Fingerprint::from_u64(4)],
                fragment_fingerprints: vec![Fingerprint::from_u64(5)],
            },
        }),
        responder_heads: f.heads,
    });
    assert_golden(&msg, GOLDEN_BATCH_SYNC_RESPONSE_OK)
}

